pub(crate) fn check_texts_all_chars(element: &Ty, items: &[Expr]) -> bool {
    let (bytes, inner) = match element {
        Ty::Named { name, args, view } => { let view = *view; (!view && name == "u8" && args.is_empty(), if !view && name == "Vec" && args.len() == 1 { (*nikaia_std::index::get(&args, 0)).clone() } else { Ty::Unknown }) },
        _ => (false, Ty::Unknown),
    };
    for item in items.iter() {
        match item {
            Expr::LitChar(..) => { if !bytes { return false; } },
            Expr::ListLit { items: nested, .. } => { if nested.is_empty() || !check_texts_all_chars(&inner, nested) { return false; } },
            _ => { return false; },
        }
    }
    bytes || !inner.is_unknown()
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
pub(crate) fn check_texts_all_text(element: &Ty, items: &[Expr]) -> bool {
    for item in items.iter() { if !check_texts_text_for(element, item) { return false; } }
    true
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
pub(crate) fn check_texts_text_for(element: &Ty, item: &Expr) -> bool {
    match element {
        Ty::Nullable(inner) => { let inner = nikaia_std::boxed::open(inner); return check_texts_is_null(item) || check_texts_text_for(inner, item); },
        _ => { },
    }
    if a_plain_string(element) { return a_text_literal_expr(item); }
    let each: Vec<Ty> = match element {
        Ty::Tuple(each) => each.to_owned(),
        _ => vec![],
    };
    if each.is_empty() { return false; }
    match item {
        Expr::Tuple(parts, _) => (parts.len() as i64) == each.len() as i64 && check_texts_tuple_all_text(&each, parts),
        _ => false,
    }
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
pub(crate) fn check_texts_tuple_all_text(each: &[Ty], parts: &[Expr]) -> bool {
    let mut i: i64 = 0;
    while ((i) as usize) < parts.len() {
        if !check_texts_text_for(nikaia_std::index::get(&each, (i) as usize), nikaia_std::index::get(&parts, (i) as usize)) { return false; }
        i += 1;
    }
    true
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
